function fetchBanlist(id){if(!banlistCache.has(id))banlistCache.set(id,fetch('banlists/'+id+'.json',{signal:AbortSignal.timeout(15000)}).then(r=>r.ok?r.json():null).catch(()=>null).then(l=>{if(!l?.cards)banlistCache.delete(id);return l?.cards?l:null}));return banlistCache.get(id)}
function presetFor(d,id){const {banlistVariants,banlistPending,...rest}=d,v=banlistVariants?.[id];return v?{...rest,...v}:banlistPending?.[id]?{...rest,pendingNote:banlistPending[id]}:rest}
function banlistName(id){const m=/^tcg-(\d{4})-(\d\d)-(\d\d)$/.exec(id);return (m?'TCG Advanced · '+Number(m[3])+' '+['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(m[2])-1]+' '+m[1]:id)+(id===banlistIndex.default?' (default)':'')}
function fillBanlistSelect(){const sel=$('#banlist');if(!sel)return;sel.innerHTML=banlistIndex.lists.map(id=>`<option value="${esc(id)}">${esc(banlistName(id))}</option>`).join('');sel.value=banlist?.id||banlistIndex.default}
async function chooseBanlist(id){const list=await fetchBanlist(id);if(!list){notify('That banlist could not load. Keeping '+(banlist?.label||'the current list')+'.');fillBanlistSelect();return}banlist=list;rememberBanlist(id);const custom=decks.filter(d=>d.id.startsWith('custom-'));decks=[...baseDecks.map(d=>presetFor(d,id)),...custom];fillBanlistSelect();drawDecks()}
function deckProblems(d){return banlist&&db&&typeof validateDeck==='function'?validateDeck(d,db,banlist).errors.filter(e=>e.code!=='NO_SCRIPT').map(describeProblem):[]} // typeof guard: test harnesses that strip imports run without the validator
function deckWarning(d){const missing=unsupportedCards(d),probs=deckProblems(d);return [missing.length?'Missing effect scripts: '+missing.join(', ')+'.':'',probs.length&&d.pendingNote?d.pendingNote:'',...probs].filter(Boolean).join(' ')}
function banlistStamp(d){return !banlist?'Banlist not loaded, so this deck isn\'t checked.':deckProblems(d).length?'':'Checked against '+banlist.label+(String(banlist.status||'').startsWith('SEED')?' (seed list; official check pending)':'')+' ✓'}
function deckInfo(d){openModal(`<p class="eyebrow">YOUR DECK COLLECTION</p><h2>${esc(d.name)}</h2><p class="muted">${esc(d.subtitle)} · ${esc(d.source)}<br>${esc(d.format)}. ${esc(banlistStamp(d))}</p>${deckWarning(d)?`<p class="script-warning" role="alert">${esc(deckWarning(d))} This deck cannot start until that's fixed.</p>`:''}<button class="primary" id="use-deck">Pilot this deck</button> <button class="quiet" id="rival-deck">Face this deck</button> <button class="quiet" id="export-deck">Export .ydk</button><div class="deck-list">${['main','extra','side'].map(z=>`<section><h3>${z==='main'?'Main Deck':z==='extra'?'Extra Deck':'Side Deck'} · ${d[z].length}</h3>${countRows(d[z]).map(([id,n])=>`<div class="deck-row"><span>${n} ×</span><button data-card="${id}">${esc(name(id))}</button></div>`).join('')}</section>`).join('')}</div>`);$('#use-deck').onclick=()=>{$('#deck-a').value=d.id;$('#seat').value='0';syncDeckSelection();modal.close()};$('#rival-deck').onclick=()=>{$('#deck-b').value=d.id;$('#seat').value='0';syncDeckSelection();modal.close()};$('#export-deck').onclick=()=>download('#created by Duel Doctrine Lab\n#main\n'+d.main.join('\n')+'\n#extra\n'+d.extra.join('\n')+'\n!side\n'+d.side.join('\n')+'\n',d.id+'.ydk')}
document.addEventListener('keydown',e=>{const n=e.target.closest?.('[data-inspect]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();dossier(Number(n.dataset.inspect))}});
document.addEventListener('click',e=>{const node=e.target.closest?.('[data-card]');if(node)dossier(Number(node.dataset.card))});
function drawDecks(){const a=$('#deck-a').value,b=$('#deck-b').value;$('#deck-grid').innerHTML=decks.map(d=>`<button class="deck-tile" data-deck="${esc(d.id)}" data-deck-theme="${esc(d.id)}">${image(d.boss)}<div class="tile-body"><div class="tile-accent"></div><h3>${esc(d.name)}</h3><p>${esc(d.subtitle)}</p><div class="counts"><span>${d.main.length} MAIN</span><span>${d.extra.length} EXTRA</span><span>${d.side.length} SIDE</span></div></div></button>`).join('');for(const sel of [$('#deck-a'),$('#deck-b')])sel.innerHTML=decks.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(d.subtitle.split(' · ')[0])}</option>`).join('');$('#deck-a').value=a||'branded';$('#deck-b').value=b||'mikanko';syncDeckSelection();$('#deck-grid').onclick=e=>{const n=e.target.closest('[data-deck]');if(n)deckInfo(decks.find(d=>d.id===n.dataset.deck))}}
