  if(pendingChainDecision?.preview&&humanFlow.current){pendingChainDecision={message:x,previousWasAi,preview:true};if(changed)renderDecision(x);return}
  pendingChainDecision={message:x,previousWasAi};
  $('#choices').innerHTML='';$('#selection-bar').hidden=true;
  $('#decision-title').textContent='Get ready…';
  $('#decision-note').textContent='Showing duel events. Your choices will appear when the scene finishes.';
  $('#decision-note').hidden=false;$('#decision-live').textContent='';
