function humanReadingHeld(){return humanHolds.held||cardHeld||!!document.querySelector('#modal[open],#duel-controls[open]')}
function drainHumanChoice(){if(disabled||!state||state.finished||$('#duel').hidden)return;const msg=humanFlow.drain({fxBusy,held:humanReadingHeld()});if(!msg)return;busy=true;syncHumanChoiceStatus();worker?.postMessage(msg)}
function reply(response,automatic=false){if(!automatic)shell?.play.manual();if(busy||disabled)return;if(humanFlow.current){if(!humanFlow.choose(response,document.activeElement?.textContent?.trim()||'Your choice'))return;sound.play('tap');syncHumanChoiceStatus();queueMicrotask(drainHumanChoice);return}if(fxBusy)return;sound.play('tap');busy=true;$('#choices').querySelectorAll('button').forEach(n=>n.disabled=true);$('#confirm').disabled=true;worker.postMessage({type:'reply',response,revision:state.revision})}
$('#pause').onclick=()=>humanHolds.manual(!computerPaused);$('#step').onclick=()=>{if(presentation.active){presentation.skip();return}worker?.postMessage({type:'step',...invalidateHumanContext()})};$('#take-seat').onclick=()=>{$('#mode').value='play';selectModePace();worker?.postMessage({type:'control',seat:1-view,...invalidateHumanContext()})};$('#study').onchange=e=>worker?.postMessage({type:'study',value:e.target.checked});$('#lab-coach')&&($('#lab-coach').onchange=e=>{preferences.coach=e.target.checked;applyPreferences()});$('#lab-graphics')&&($('#lab-graphics').onchange=e=>{preferences.graphics=e.target.value;applyPreferences()});$('#lab-skip-cutins')&&($('#lab-skip-cutins').onchange=e=>{preferences.skipCutins=e.target.checked;applyPreferences()});{const panel=$('#event-log-panel');if(panel){const saved=preferences.eventLogOpen;if(saved===false||(saved===undefined&&window.innerWidth<900))panel.removeAttribute('open');panel.addEventListener('toggle',()=>{preferences.eventLogOpen=panel.open;savePreferences()})}}$('#speed').onchange=e=>{worker?.postMessage({type:'speed',value:Number(e.target.value)});syncDuelControls()};$('#extra').onclick=()=>state&&pile(view,64);$('#new').onclick=()=>{resetHumanInteraction();humanClientSession='';syncHumanChoiceStatus();if($('#duel-controls').open)$('#duel-controls').close();$('#duel-controls-toggle').hidden=true;cardHeld=false;setArenaFocus(false);if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});presentation.reset();shuffleOverlay.reset();worker?.postMessage({type:'stop'});$('#duel').hidden=true;document.body.classList.remove('in-duel');sound.stopMusic();$('#setup').hidden=false;$('#notice').hidden=true;window.scrollTo({top:0,behavior:'smooth'})};
function download(text,filename){const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#save-log').onclick=()=>state&&worker.postMessage({type:'export'});const replayButton=document.createElement('button');replayButton.textContent='Save replay';replayButton.onclick=()=>state&&worker.postMessage({type:'export-replay'});$('#save-log').after(replayButton);
const replayImport=document.createElement('input');replayImport.type='file';replayImport.accept='.json';replayImport.hidden=true;const importButton=document.createElement('button');importButton.textContent='Open saved replay';importButton.onclick=()=>replayImport.click();$('#game-seed').closest('label').after(importButton,replayImport);
replayImport.onchange=async()=>{try{const file=replayImport.files[0];if(!file)return;const r=JSON.parse(await file.text());if(r.version!=='2.2.0-rc'||!Array.isArray(r.decks)||r.decks.length!==2||!Array.isArray(r.responses)||r.responses.length>10000||![0,1].includes(r.first)||!Number.isInteger(r.seed)||r.seed<1||r.seed>4294967295)throw Error('This is not a supported Duel Lab replay.');
 const chosen=r.decks.map(d=>{let existing=decks.find(x=>x.id===d.id&&JSON.stringify(x.main)===JSON.stringify(d.main)&&JSON.stringify(x.extra)===JSON.stringify(d.extra));if(existing)return existing;const loaded=expandYdk('#main\n'+d.main.join('\n')+'\n#extra\n'+d.extra.join('\n')+'\n!side\n'+(d.side||[]).join('\n'),db);loaded.name=d.name||'Replay deck';decks.push(loaded);return loaded});drawDecks();$('#deck-a').value=chosen[0].id;$('#deck-b').value=chosen[1].id;$('#game-seed').value=String(r.seed);$('#first').value=String(r.first);$('#mode').value='watch';selectModePace();importedResponses=r.responses;$('#start').click();notify('Saved responses restored. Playback is paused at the saved position.');
 }catch(e){importedResponses=null;notify(e.message,true)}finally{replayImport.value=''}};

$('#help').onclick=()=>openModal('<p class="eyebrow">DUEL DOCTRINE LAB · 2.2.0-rc</p><h2>Watch. Pause. Understand.</h2><p>Choose your matchup and AI Watch, Deal a Hand, Play vs AI or Replay a Seed. Learning pace gives every resolving link four seconds, with extra time for longer text. Chains build quickly, then resolve from the top down. Tap to continue is optional. Skip FX skips only the current scene.</p><p>Open the gear for pace, five sound buses, spoken callouts, reduced motion and the coach. The coach explains each real decision. In the journal, tap a moment to rewind to that decision; bookmarks are saved on this device. Rewind pauses the duel so you can inspect it before resuming.</p><p>Long-press a field card to read its text; swipe up on your hand to spread it. Portrait offers an overview; landscape is recommended. Use your browser’s Install / Add to home screen for offline play after the offline download completes.</p><p>The Optimal pilot uses bounded engine-replayed search, resource preservation and a blunder guard. It cannot guarantee perfect play against hidden information. The native engine decides legality. Best-of-three siding is a later stage.</p>');
$('#preview-fx').onclick=()=>{if(state&&!state.finished){humanHolds.manual(true);presentation.skip()}sound.unlock();openModal('<p class="eyebrow">FUSION ROOM · SOUND STUDIO</p><h2>Hear the duel.</h2><p>Metal chains, heavy impacts and energy swells. Tap a cue to hear it.</p><label class="studio-volume">Volume <input id="studio-volume" type="range" min="0" max="100" value="'+Math.round(preferences.volume*100)+'"></label><div class="sound-board">'+[...Object.entries(PHASE_CUES).map(([id,p])=>[p[1],p[0],p[2],'PHASE']),...Object.entries(MECHANICS).map(([cue,p])=>[cue,p[0],p[1],'MECHANIC']),...['ice','crimson','mikanko','striker','lunar'].map(theme=>['victory:'+theme,theme.toUpperCase()+' VICTORY','var(--palette-434)','DUEL RESULT']),...['ice','crimson','sanctifire','lunar','mikanko','striker'].map(theme=>['boss:'+theme,theme.toUpperCase()+' BOSS','var(--palette-435)','BOSS SUMMON'])].map(([cue,label,color,group])=>`<button class="sound-tile" data-audition="${cue}" style="--tile-color:${color}">${label}<small>${group}</small></button>`).join('')+'</div><p class="muted">Sound on enables previews. Each new audition replaces the previous sound. Opening the studio pauses computer play; resume when you are ready.</p>');$('#studio-volume').oninput=e=>{preferences.volume=Number(e.target.value)/100;applyPreferences()};$('#modal-body').querySelectorAll('[data-audition]').forEach(button=>button.onclick=()=>{sound.stop();sound.unlock();const [cue,theme]=button.dataset.audition.split(':');sound.play(cue,theme);button.classList.remove('audition');void button.offsetWidth;button.classList.add('audition')})};
$('#credits').onclick=()=>openModal('<p class="eyebrow">BUILT ON AN OPEN FOUNDATION</p><h2>Engine & source credits</h2><p>Duel Doctrine Lab is an independent personal practice app. It is not affiliated with Konami or YGO Lab.</p><p>The duel engine is <a href="https://github.com/edo9300/ygopro-core" target="_blank" rel="noreferrer">EDOPro / ygopro-core</a>, exposed through <a href="https://github.com/n1xx1/ocgcore-wasm" target="_blank" rel="noreferrer">ocgcore-wasm</a>. Card data and effect scripts come from <a href="https://github.com/ProjectIgnis/BabelCDB" target="_blank" rel="noreferrer">BabelCDB</a> and <a href="https://github.com/ProjectIgnis/CardScripts" target="_blank" rel="noreferrer">Project Ignis CardScripts</a>.</p><p>Artwork comes from the existing Doctrine projects and YGOPRODeck. Yu-Gi-Oh names and card imagery belong to their respective owners.</p><p><a href="source.zip" download>Download the lab source</a> · <a href="engine-source.zip" download>Engine source</a> · <a href="licenses/AGPL-3.0.txt" target="_blank">Engine licence</a> · <a href="licenses/wrapper.txt" target="_blank">Wrapper licence</a></p><p class="muted">This version provides engine-checked duels, sound effects, summon presentation and explanations of independent procedural pilots’ choices. It does not include tournament-strength deck pilots, a complete coaching system, between-game siding. Replay rewind is now available.</p>');
shell=installShell({getDecision:()=>latestDecisionMessage,submit:reply,navigate:showScreen,inspect:dossier,preferences,applyPreferences,sound,presentation,getState:()=>state,getMatch:()=>matchInfo,getDecks:()=>duelDecks||[],getWorker:()=>worker,notify,openModal,beforeRewind:()=>{shuffleOverlay.reset();return invalidateHumanContext()}});
async function loadCardLibrary(){
 const w=new Worker('library-worker.mjs',{type:'module'});
 return await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{w.terminate?.();reject(Error('Card library timed out after 15 seconds. Tap Retry to try again.'))},15000);
 w.onmessage=({data:x})=>{if(x.type==='export-replay'){download(JSON.stringify(x.replay,null,2),'doctrine-replay.json');return}if(x.type==='load-progress')$('#load-status').textContent=x.message;if(x.type==='library'){clearTimeout(timer);w.terminate?.();resolve(x.db)}if(x.type==='error'){clearTimeout(timer);w.terminate?.();reject(Error(x.message))}};
 w.onerror=e=>{clearTimeout(timer);w.terminate?.();reject(Error(e.message||'Card library failed to load.'))};w.postMessage({type:'load-library'});});
}
async function initialiseLibrary(){
 $('#start').disabled=true;$('#start').textContent='Loading card library…';$('#load-status').textContent='Fetching and decompressing cards in the background…';let progress=document.querySelector('#library-progress');if(!progress){progress=document.createElement('progress');progress.id='library-progress';progress.setAttribute('aria-label','Loading card library');$('#load-status').after(progress)}progress.hidden=false;
 let retry=document.querySelector('#retry-library');if(retry)retry.hidden=true;
 try{const [cards,data,list]=await Promise.all([loadCardLibrary(),fetch('decks.json',{signal:AbortSignal.timeout(15000)}).then(r=>{if(!r.ok)throw Error('Decks could not load.');return r.json()}),fetch('banlists/index.json',{signal:AbortSignal.timeout(15000)}).then(r=>r.ok?r.json():null).catch(()=>null).then(async idx=>{if(idx&&typeof idx.default==='string'&&Array.isArray(idx.lists)&&idx.lists.includes(idx.default))banlistIndex=idx;const want=savedBanlist(),id=banlistIndex.lists.includes(want)?want:banlistIndex.default;return (await fetchBanlist(id))??(id!==banlistIndex.default?await fetchBanlist(banlistIndex.default):null)})]);banlist=list&&list.cards?list:null;db=cards;notes=data.notes;baseDecks=data.decks;decks=baseDecks.map(d=>presetFor(d,banlist?.id));fillBanlistSelect();
 try{const saved=JSON.parse(localStorage.getItem('doctrine-lab-decks-v1')||'[]');for(const d of saved){if(d?.id?.startsWith('custom-')&&d.main?.length>=40&&d.main?.length<=60&&d.extra?.length<=15&&d.side?.length<=15&&[...d.main,...d.extra,...d.side].every(id=>db[id]))decks.push(d)}}catch{}
 drawDecks();progress.hidden=true;$('#start').disabled=false;$('#start').textContent='Enter the duel room →';$('#load-status').textContent=decks.filter(d=>!d.id.startsWith('custom-')).length+' saved decks · Choose either seat · No account setup';
 }catch(e){progress.hidden=true;$('#load-status').textContent=e.message;$('#start').textContent='Unable to load the lab';if(!retry){retry=document.createElement('button');retry.id='retry-library';retry.textContent='Retry card library';$('#load-status').after(retry);retry.onclick=initialiseLibrary}retry.hidden=false;notify(e.message,true)}
}
await initialiseLibrary();
