{const quick=document.querySelector('#quick-pace'),pace=document.querySelector('#lab-pace');if(quick&&pace){const sync=()=>{for(const b of quick.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.pace===pace.value))};quick.addEventListener('click',e=>{const b=e.target.closest('button[data-pace]');if(!b||pace.value===b.dataset.pace)return;pace.value=b.dataset.pace;pace.dispatchEvent(new Event('change',{bubbles:true}));sync()});pace.addEventListener('change',sync);document.addEventListener('duel-presentation-event',sync);sync()}}
