{for(const pane of document.querySelectorAll('.coach-pane,.play-pane,.journal-pane')){if(pane.querySelector(':scope > .pane-close'))continue;const b=document.createElement('button');b.type='button';b.className='pane-close';b.textContent='\u2715 Close';b.setAttribute('aria-label','Close and return to the field');b.addEventListener('click',()=>showScreen('field'));pane.prepend(b)}
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#duel')?.dataset.screen&&document.querySelector('#duel').dataset.screen!=='field'&&!document.querySelector('dialog[open]'))showScreen('field')})}
